window.__posterData({"id": "sara-vendel", "name": "Sara Vendel", "folder": "Week1_Poster_SaraVendel-1", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// the first time i asked it to \"refactor the code without changing functionality\" it had problem to do so. the rectangle went up in the corner and didn't turn when the mouse was hovering it. so i had to ask it again by saying that it didn't have the same functions. the ai corrected it, but also changed the font to this courier new.\n\n// i specifically asked it to make the rektangle glow as well as the text and the balls. the ai made the rectangle only have the outline that glows and the circles got some cool effects and i really liked it! the text is also glowing but in a more suddle way, wich makes it easy to read so i'm not mad about it. the rectangle also feels more like a portal now so i didn't asked ai to fill it again. when i asked it to do their own thing based on what i already asked it to do it gave the circles new effects that made them change color when i clicked the mouse but also made them bigger when mouse is pressed. it also added the glitter in the background. i really liked the new effects it coded!\n\nlet angle = 0;\nlet distMouse = 100;\n\nlet img;\n\nlet x = [];\nlet speed = [];\n\nlet w = 40;\nlet nrBalls = 20;\nlet fontBold;\n\nlet ballColors = [];\nlet ballSize = 40;\n\nlet sparkles = [];\n\nasync function setup() {\n  createCanvas(600, 800);\n  rectMode(CENTER);\n  angleMode(DEGREES);\n  colorMode(RGB, 255);\n\n  // background\n  img = await loadImage('forest.jpg');\n  describe('forest');\n\n  // bright neon color to the circles\n  let neonPalette = [\n    [80, 255, 255],   // Cyan\n    [100, 255, 180],  // Mintgrön\n    [220, 255, 100],  // Lime\n    [255, 255, 130],  // Ljusgul\n    [255, 150, 240],  // Ljusrosa\n    [150, 180, 255],  // Ljusblå\n    [190, 140, 255]   // Lila\n  ];\n\n  // the balls positions, speed and colors\n  for (let i = 0; i < nrBalls; ++i) {\n    x[i] = random() * (width - w);\n    speed[i] = random(10);\n\n    ballColors[i] = color(\n      ...random(neonPalette)\n    );\n  }\n\n  // the glitter in the background\n  for (let i = 0; i < 70; i++) {\n    sparkles.push({\n      x: random(width),\n      y: random(height),\n      size: random(1, 4),\n      alpha: random(100, 255)\n    });\n  }\n}\n\nfunction draw() {\n  image(img, 0, 0, width, height);\n\n  drawSparkles();\n\n  let distance = dist(\n    mouseX,\n    mouseY,\n    width / 2,\n    height / 2\n  );\n\n  // the rectangle spins around when mouse is hovering it\n  if (distance < distMouse) {\n    angle += 1;\n  }\n\n  // the rectangle glow\n  push();\n  translate(width / 2, height / 2);\n  rotate(angle);\n\n  noFill();\n\n  for (let i = 5; i >= 1; i--) {\n    stroke(255, 100, 230, 18);\n    strokeWeight(i * 5);\n    rect(0, 0, 400, 200);\n  }\n\n  stroke(255, 140, 245);\n  strokeWeight(3);\n  rect(0, 0, 400, 200);\n\n  stroke(255, 240, 255);\n  strokeWeight(1);\n  rect(0, 0, 400, 200);\n\n  // the balls change size when mouse is pressed\n  ballSize = mouseIsPressed ? 60 : 40;\n\n  // the balls glow and colors\n  for (let i = 0; i < nrBalls; ++i) {\n    let ballX = x[i] + w / 2;\n    let ballY = i * 100 + w / 2;\n\n    let c = ballColors[i];\n\n    // the halo glow\n    noStroke();\n    fill(red(c), green(c), blue(c), 25);\n    circle(ballX, ballY, ballSize * 2.5);\n\n    fill(red(c), green(c), blue(c), 55);\n    circle(ballX, ballY, ballSize * 1.8);\n\n    fill(red(c), green(c), blue(c), 100);\n    circle(ballX, ballY, ballSize * 1.35);\n\n    // the color of the ball\n    fill(c);\n    circle(ballX, ballY, ballSize);\n\n    // the light dot that makes the ball get this shining effect\n    fill(255, 255, 255, 210);\n    circle(\n      ballX - ballSize * 0.12,\n      ballY - ballSize * 0.12,\n      ballSize * 0.3\n    );\n\n    // movement\n    x[i] += speed[i];\n\n    if (x[i] <= 0 || x[i] >= width - w) {\n      speed[i] *= -1;\n    }\n  }\n\n  pop();\n\n  // the neon headline\n  textFont('Courier New');\n  textSize(80);\n  textStyle(BOLD);\n  textAlign(LEFT);\n\n  fill(255, 0, 200, 70);\n  text('FOREST RAVE', 42, 152);\n  text('FOREST RAVE', 38, 148);\n\n  fill(255, 180, 245);\n  text('FOREST RAVE', 40, 150);\n\n  // my name\n  textSize(30);\n  textStyle(NORMAL);\n  fill(255, 180, 240);\n  text('Sara Vendel', 100, 700);\n}\n\n// the glitter (never heard of alpha but thats interesting)\nfunction drawSparkles() {\n  noStroke();\n\n  for (let i = 0; i < sparkles.length; i++) {\n    let s = sparkles[i];\n\n    s.alpha += random(-25, 25);\n    s.alpha = constrain(s.alpha, 70, 255);\n\n    fill(255, 240, 255, s.alpha);\n    circle(s.x, s.y, s.size);\n\n    if (s.size > 3) {\n      stroke(180, 255, 255, s.alpha);\n      strokeWeight(1);\n\n      line(s.x - 4, s.y, s.x + 4, s.y);\n      line(s.x, s.y - 4, s.x, s.y + 4);\n\n      noStroke();\n    }\n  }\n}\n\n// the color change when mouse is pressed\nfunction mousePressed() {\n  let neonPalette = [\n    [80, 255, 255],\n    [100, 255, 180],\n    [220, 255, 100],\n    [255, 255, 130],\n    [255, 150, 240],\n    [150, 180, 255],\n    [190, 140, 255]\n  ];\n\n  for (let i = 0; i < nrBalls; ++i) {\n    ballColors[i] = color(...random(neonPalette));\n  }\n}\n\n// the end! with my comments and the ai code it went from 67 lined to 207 lines...", "assets": {"forest.jpg": {"mime": "image/webp", "b64": ""}}});
